SELECT id, ds_id, task_type, task_name, status, pause_flag, trigger_type, last_run_time, last_result, last_error, run_count, remark, schedule_cron, next_run_time, create_time, update_time FROM kb_crawl_task
AND ds_id = #{dsId}
AND status = #{status}
ORDER BY ds_id ASC, task_type ASC, id DESC

SELECT id, ds_id, task_type, task_name, status, pause_flag, trigger_type, last_run_time, last_result, last_error, run_count, remark, schedule_cron, next_run_time, create_time, update_time FROM kb_crawl_task WHERE pause_flag = 0 AND status <> 'running'
AND status = #{status}
ORDER BY ISNULL(last_run_time), last_run_time ASC, id ASC
